\section{Extended Analysis and Limitations}
\label{sec:extended_discussion}

This section provides supporting tables for cross-scorer validation (Tables~\ref{tab:crossscorer}--\ref{tab:anova_crossscorer}), followed by extended limitations, ablation studies, and domain-specific analyses.

\noindent\begin{minipage}{\columnwidth}
\centering
\captionof{table}{Cross-scorer validation on Qwen-generated text. Alternative scorers (Pythia-1.4B, OLMo-1B) preserve feature ranking ($\rho > 0.90$) and rewrite-mode $\Kempirical = 2$, but reduce continuation-mode $\Kempirical$ from 2 to 1.}
\label{tab:crossscorer}
\resizebox{\columnwidth}{!}{\input{tables/tab_crossscorer}}
\end{minipage}

\begin{table}[h]
\centering
\small
\caption{Three-way ANOVA (Generator $\times$ Scorer $\times$ Depth-Pair) on per-fold pairwise $\auc$ values (Type~II SS). DV = per-fold AUC; $N{=}300$ (12 cells $\times$ 5 folds $\times$ 5 depth-pairs; 3 generators $\times$ 4 scorers). Scorer is statistically significant ($p < .001$) but has a small effect size ($\eta^2_p = 0.19$) relative to Depth-Pair ($\eta^2_p = 1.00$) and Generator ($\eta^2_p = 0.89$), indicating that scorer choice has a detectable but practically minor influence on depth discrimination (Scorer $\eta^2_p$ is approximately 5$\times$ smaller than Generator and dwarfed by Depth-Pair). Per-fold AUC values within the same generator share seed documents across folds and are not fully independent; we therefore rely on effect-size ratios rather than $p$-values for interpretation.}
\label{tab:anova_crossscorer}
\begin{tabular}{lrrrr}
\toprule
\textbf{Source} & \textbf{df} & $F$ & $p$ & $\eta^2_p$ \\
\midrule
Generator     & 2  & 926.8  & ${<}.001$  & .885 \\
Scorer        & 3  & 19.02  & ${<}.001$  & .192 \\
Depth-Pair    & 4  & 24736  & ${<}.001$  & .998 \\
Gen$\times$Scorer & 6 & 8.16 & ${<}.001$ & .170 \\
Gen$\times$Depth  & 8 & 993.7 & ${<}.001$ & .971 \\
Scorer$\times$Depth & 12 & 2.45 & .005 & .109 \\
Residual      & 240 & & & \\
\bottomrule
\end{tabular}
\end{table}

\subsection{Extended Limitations}
\label{sec:extended_limitations}

\emph{Prompt-chain versus retrain-chain.}
Retrain-chain validation (Pythia-1.4B LoRA, 5 generations) yields $\Kempirical{\geq}4$ (Table~\ref{tab:retrain_ci}), far exceeding prompt-chain $\Kempirical{=}2$.
All pairwise CIs have lower bounds well above $\theta{=}0.60$ ($p < 0.001$), statistically confirming $\Kempirical{\geq}4$.
The elevated signal arises from cumulative model-adaptation artifacts (vocabulary narrowing, repetition bias) rather than text-intrinsic degradation; prompt-chain $\Kempirical$ is the operationally relevant boundary for data curation.

\begin{table}[h]
\centering
\small
\caption{Retrain-chain pairwise $\auc$ with bootstrap 95\% CIs (Pythia-1.4B LoRA, 5 generations). All CI lower bounds $\gg \theta{=}0.60$.}
\label{tab:retrain_ci}
\begin{tabular}{lccc}
\toprule
\textbf{Pair} & $\auc$ & \textbf{95\% CI} & $p$ \\
